function User(name) {
  this.name = name;
}

User.prototype.greet = function () {
  return `Hello ${this.name}`;
};

const user = new User('Alex');

Object.getPrototypeOf(user) === User.prototype; // true
User.prototype === user.__proto__; // true

const parent = { role: 'admin' };
const child = Object.create(parent);

child.name = 'Alex';

child.role; // 'admin'
child.name; // 'Alex'

Object.hasOwn(child, 'role'); // false
'role' in child; // true

child.role = 'user';
child.role; // 'user'

function Person(name) {
  this.name = name;
}

Person.prototype.sayHello = function () {
  return `Hello ${this.name}`;
};

const person = new Person('Alex');

person instanceof Person; // true
person.sayHello(); // 'Hello Alex'

const behavior = {
  greet() {
    return `Hello ${this.name}`;
  }
};

const user = Object.create(behavior);
user.name = 'Alex';

user.greet(); // 'Hello Alex'

